  ('c842bd76-4291-5538-8a39-fea85e0226d1', 'ba1c7842-6dd2-587d-9f4e-0465e0f094c4', 2, 'Resources deployed from templates are cheaper than resources created in the portal'),
  ('8cda5113-0a92-5ce1-9a30-7f9c7ed49e85', 'ba1c7842-6dd2-587d-9f4e-0465e0f094c4', 3, 'The same template can be redeployed to create consistent, repeatable environments'),
