  ('10814cec-b7f8-5934-9607-525de0e63a1c', '475ac71f-9407-566f-b6a3-06c02e81c74d', 2, 'Azure Advisor'),
  ('9256d3f1-b6ae-5464-8ebd-4bf113a9c2c4', '475ac71f-9407-566f-b6a3-06c02e81c74d', 3, 'Azure Service Health'),
  ('1c6b3cbb-feaf-5c60-aeb9-69f3151f803a', '475ac71f-9407-566f-b6a3-06c02e81c74d', 4, 'Azure Resource Manager'),
  ('ea204171-4d41-5821-9d68-63564735581c', 'fea4d1fc-4971-54da-aa38-e980ece5672c', 1, 'Log Analytics'),
  ('f174bfb8-6bc0-5788-9deb-39bc905c43b3', 'fea4d1fc-4971-54da-aa38-e980ece5672c', 2, 'Azure Cloud Shell'),
  ('d24b6ef0-ba98-5c97-9674-ad92f4efa8fa', 'fea4d1fc-4971-54da-aa38-e980ece5672c', 3, 'Resource locks'),
  ('9aa8854f-dbcd-5b68-b9ef-f83a97ff9c70', 'fea4d1fc-4971-54da-aa38-e980ece5672c', 4, 'Azure Policy'),
  ('a80fd9ba-6d46-5cc9-87e7-d8c388e9b2ca', '50a8be05-9e63-512e-bfdb-d47e6870e7ba', 1, 'Azure Advisor'),
  ('379ca621-68e4-5e8f-88f5-05147b2c7f3c', '50a8be05-9e63-512e-bfdb-d47e6870e7ba', 2, 'Management groups'),
  ('428705d2-e195-5182-9ec8-5269caabd095', '50a8be05-9e63-512e-bfdb-d47e6870e7ba', 3, 'Application Insights'),
