insert into public.question_solutions (question_id, explanation, reference_url)
select v.question_id::uuid, v.explanation, v.reference_url
from (values
  ('63f16187-3a08-5ff4-b527-e0de602606ce', 'Cloud computing delivers computing services, such as servers, storage, databases and networking, over the internet. The provider owns and runs the hardware, and you rent what you need and usually pay only for what you use.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-compute/'),
  ('48bac3ea-5b2e-5c87-98db-4a14e135f2cf', 'In the shared responsibility model the provider always secures the physical datacentre, network and hosts. With IaaS virtual machines the customer manages the operating system, including patches, plus the applications and data on it. In PaaS the provider takes over more of the stack, and in SaaS most of it.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-compute/'),
  ('aa29350c-8f7e-5dc4-a3c1-6d514409677d', 'A hybrid cloud combines a public cloud with on-premises or private infrastructure. It suits organisations that must keep some data in their own facilities, for example because of regulation or latency, while using the public cloud for other workloads.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-compute/'),
  ('60aadaf9-0a71-5393-bee8-ea54df0a1762', 'With consumption-based pricing you pay for what you use, such as compute hours or gigabytes stored. There is no up-front hardware purchase, and your costs fall when you stop or delete resources.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-compute/'),
  ('72e9faeb-4b2f-535c-9222-bf5455f53bc5', 'Customers always keep responsibility for their information and data, for their devices, and for the accounts and identities that can reach their services. The provider always handles the physical datacentre, physical network and physical hosts. Operating systems, network controls and applications shift between provider and customer depending on whether the service is IaaS, PaaS or SaaS.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-compute/'),
  ('1fde8d21-8c4b-51d1-ab86-222dfc81470a', 'In serverless computing you supply code and the platform runs and scales it, so you do not provision or manage servers. You are typically billed for the compute your code actually uses. Azure Functions is an example.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-compute/'),
  ('604531b2-b49e-5115-b7ba-00ebc7a6e3f7', 'Horizontal scaling (scaling out) adds more instances, and scaling in removes them. Vertical scaling (scaling up) gives an existing instance more CPU or memory. In the cloud, autoscale rules can add and remove instances as demand changes.', 'https://learn.microsoft.com/en-us/training/modules/describe-benefits-use-cloud-services/'),
  ('76d1cdc4-6a5f-5d1b-ba31-60909bfc96ae', 'Predictability has two sides: performance predictability, where autoscaling and load balancing keep response times steady, and cost predictability, where estimation and cost-management tools let you forecast and control spending.', 'https://learn.microsoft.com/en-us/training/modules/describe-benefits-use-cloud-services/'),
  ('023a3a8a-dba6-538d-8187-803e62c3da0e', 'Manageability covers managing the cloud, such as autoscaling, deploying from templates and monitoring with alerts, and managing in the cloud, through the portal, command-line tools, PowerShell and APIs.', 'https://learn.microsoft.com/en-us/training/modules/describe-benefits-use-cloud-services/'),
  ('fa28e60e-a11d-582a-826e-e2bc25d44cb3', 'High availability comes from removing single points of failure. Running multiple instances in separate availability zones behind a load balancer keeps the app serving users if one zone fails.', 'https://learn.microsoft.com/en-us/training/modules/describe-benefits-use-cloud-services/'),
  ('197604fc-847f-5b94-82da-81ec1780de61', 'IaaS rents basic computing building blocks, such as virtual machines, storage and networks. You manage the operating system and everything above it, while the provider runs the physical hardware.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-service-types/'),
  ('339f5fdf-79d6-5957-844a-bcb7027c3d88', 'PaaS gives developers a managed platform for building and running applications. The provider handles the servers, operating system and runtime, and the team focuses on its code and data. Azure App Service is an example.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-service-types/'),
  ('eaa51250-8ef2-55ad-b156-0317e93ede79', 'SaaS delivers a finished application over the internet, which you use without managing the underlying platform. Microsoft 365 is SaaS. Azure Virtual Machines are IaaS and Azure App Service is PaaS.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-service-types/'),
  ('9b2022bb-e422-5c4f-9762-3749ab58adf8', 'Moving from IaaS to PaaS to SaaS shifts more responsibility to the provider. IaaS customers manage the operating system, runtime, applications and data. PaaS customers manage their applications and data. SaaS customers mainly manage their data, users and settings.', 'https://learn.microsoft.com/en-us/training/modules/describe-cloud-service-types/'),
  ('e6aedb04-abf7-575e-bba1-c678ed76ff38', 'Availability zones are physically separate datacentres within an Azure region, connected by a high-speed private network. Regions that support zones have at least three, so a failure in one zone does not take down the others. Not every region supports availability zones.', 'https://learn.microsoft.com/en-us/training/modules/describe-core-architectural-components-of-azure/'),
  ('1da5f19e-d79a-5f35-87e7-8a91b662375c', 'A region pair links two regions, usually in the same geography. A small number of services use pairs for geo-replication, for example geo-redundant storage, and planned updates are staggered across a pair. Many newer regions are not paired and use availability zones instead. Microsoft advises against relying on Azure-managed failover between paired regions as your main disaster recovery plan.', 'https://learn.microsoft.com/azure/reliability/regions-paired'),
  ('17714a88-48f9-517e-be5a-d7e9781e479f', 'Management groups contain subscriptions, subscriptions contain resource groups, and resource groups contain resources. Access control and policy assigned at a higher scope are inherited by everything below it.', 'https://learn.microsoft.com/en-us/training/modules/describe-core-architectural-components-of-azure/'),
  ('2dfe5c6d-5e50-5780-a0d2-f4d688aab243', 'A resource group is a logical container for related resources that share a lifecycle. Deleting the group deletes every resource in it. Each resource lives in exactly one group, and the resources in a group can sit in different regions.', 'https://learn.microsoft.com/en-us/training/modules/describe-core-architectural-components-of-azure/'),
  ('58d51fa7-82f1-596a-94d7-c1b4107375c6', 'Sovereign regions are separate instances of Azure built for specific legal or compliance needs, such as Azure Government for US government agencies and Microsoft Azure operated by 21Vianet in China. They often offer fewer services and features than public regions.', 'https://learn.microsoft.com/en-us/training/modules/describe-core-architectural-components-of-azure/'),
  ('5faafe69-531a-5825-ae3f-b2e126dcdebe', 'Azure Functions is a serverless, event-driven compute service. Code runs when triggered, for example by an HTTP request, a timer or a new file, and the platform handles the infrastructure.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-compute-networking-services/'),
  ('8ef6cf23-8f7b-5aa5-a3a3-e5d0b89137e4', 'Containers bundle an app and its dependencies and share the host operating system kernel. That makes them lighter and quicker to start than virtual machines, which each run a full guest operating system.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-compute-networking-services/'),
  ('e4b358ca-6bde-5e3b-9d54-c647c421cca1', 'Virtual Machine Scale Sets let you create and manage a group of identical, load-balanced virtual machines, and the instance count can grow or shrink automatically based on demand or a schedule.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-compute-networking-services/'),
  ('a96119b7-cb28-5523-8d2c-b3b84cc2ebdc', 'ExpressRoute creates private connections between on-premises infrastructure and Azure through a connectivity provider, without going over the public internet. VPN Gateway also links networks, but over an encrypted tunnel across the internet.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-networking-services/'),
  ('45b9fb90-73ed-5179-86fa-09a479ea4b2a', 'A private endpoint is a network interface with a private IP address from your virtual network. It connects you privately to a service powered by Azure Private Link, such as a storage account, so traffic stays off the public internet.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-networking-services/'),
  ('8c0cef83-270b-5e5d-95c1-fa4afa5f27cc', 'Blob Storage is object storage for massive amounts of unstructured data, such as images, video, logs and backups. Azure Files offers file shares, Queue Storage offers messaging and Table Storage holds structured NoSQL data.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-storage-services/'),
  ('32f1a4b5-394c-5543-b593-bcc4c5792ccf', 'Archive has the lowest storage cost. Blobs in it are offline and must be rehydrated to an online tier before they can be read, which can take hours. Hot, cool and cold are online tiers that can be read immediately, with storage cost falling and access cost rising from hot to cold.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-storage-services/'),
  ('c453f925-3db3-5549-822e-3f8024ba399e', 'GZRS copies data synchronously across three availability zones in the primary region and asynchronously to a second region. GRS also replicates to a second region, but its primary copies are locally redundant. ZRS and LRS keep everything in the primary region.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-storage-services/'),
  ('42898b53-bdb6-5bd5-ac43-fb95d623b998', 'Azure Data Box is a physical device that Microsoft ships to you. You copy your data onto it and ship it back to be loaded into Azure, which suits very large data sets or slow connections. AzCopy, Storage Explorer and File Sync all rely on the network.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-storage-services/'),
  ('109c2dd0-09b5-5926-8b27-44285784a5d5', 'Microsoft Entra Domain Services provides managed domain services, such as domain join, Group Policy, LDAP and Kerberos or NTLM authentication, without you deploying domain controllers. Microsoft Entra ID is the cloud-based identity and access management service.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-identity-access-security/'),
  ('bdb0ce65-e5d3-5bc0-896a-b96e5e8f8fde', 'Passwordless methods replace the password with something you have, such as a security key or phone, together with something you are or know, such as a biometric or PIN. Windows Hello for Business, Microsoft Authenticator and FIDO2 security keys are examples.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-identity-access-security/'),
  ('0db8182a-4b0e-5130-9527-123c23b9fd5a', 'Conditional Access evaluates signals such as user, location, device and risk when someone signs in, then applies a decision, for example allow, block or require multifactor authentication.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-identity-access-security/'),
  ('1f7c993e-de7e-5f78-a2b9-74615c929948', 'Azure RBAC grants access through role assignments, which combine a security principal (who), a role definition (what they can do) and a scope (where). Assigning a suitable role at the resource group scope follows the principle of least privilege.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-identity-access-security/'),
  ('a0b363db-d6b7-5d50-b195-a882ad040114', 'Zero Trust rests on three principles: verify explicitly, use least-privilege access, and assume breach. Every request is authenticated and authorised using all available signals, access is limited to what is needed, and systems are designed expecting that an attacker may already be inside.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-identity-access-security/'),
  ('b9718a08-7f61-5d4c-ae34-1c0bdea954ff', 'Defense in depth protects resources in layers: physical security, identity and access, perimeter, network, compute, application and data. The perimeter layer uses protections such as DDoS protection and firewalls to filter large-scale attacks before they reach your network. If one layer is breached, the others still protect you.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-identity-access-security/'),
  ('c6be6279-79a7-56b3-9e66-c9ff86afe9e4', 'Microsoft Defender for Cloud assesses and strengthens your security posture, with recommendations and a secure score, and provides threat protection for workloads in Azure, on-premises and other clouds.', 'https://learn.microsoft.com/en-us/training/modules/describe-azure-identity-access-security/'),
  ('8f046d23-30b1-595a-8d8b-9cae81eb1433', 'Factors that affect Azure cost include resource type, how much you consume, geography (region), network traffic, subscription type and Marketplace purchases. The same resource can cost different amounts in different regions.', 'https://learn.microsoft.com/en-us/training/modules/describe-cost-management-azure/'),
  ('b73656ee-4eb7-5754-93ab-96329e3a7ca1', 'Azure does not charge for data transferred into its datacentres. Data transferred out is charged, with a monthly free allowance for internet egress, and rates depend on factors such as the destination zone. Network traffic is one of the factors that affect cost.', 'https://azure.microsoft.com/pricing/details/bandwidth/'),
  ('1c0f5765-726b-5007-bdba-ae7d2517d1d9', 'The pricing calculator lets you configure Azure services, regions and sizes and see an estimated cost before you deploy. Use Microsoft Cost Management to track what you actually spend.', 'https://learn.microsoft.com/en-us/training/modules/describe-cost-management-azure/'),
  ('baa94553-d2f1-534e-8523-9ade11dc01d8', 'Microsoft Cost Management lets you analyse spending, create budgets and set alerts that notify people when costs reach a threshold you choose.', 'https://learn.microsoft.com/en-us/training/modules/describe-cost-management-azure/'),
  ('b42f6555-a55f-5ab7-abd6-f2b1fd87303a', 'Tags are name and value pairs you attach to resources, resource groups and subscriptions. They help you organise resources and report on costs, for example Department = Finance. They are metadata only, and by default they are not inherited.', 'https://learn.microsoft.com/en-us/training/modules/describe-cost-management-azure/'),
  ('7243542b-1365-5f7a-a13f-47315a6c6dbd', 'Azure Policy defines rules, such as allowed regions or allowed VM sizes, evaluates resources against them, and can deny non-compliant deployments. RBAC answers who can do what, while Policy governs what resources can look like.', 'https://learn.microsoft.com/en-us/training/modules/describe-features-tools-azure-for-governance-compliance/'),
  ('f6b545b3-d9c0-51b5-8b89-4b4719ac9432', 'A CanNotDelete lock lets authorised users read and modify a resource but not delete it. A ReadOnly lock allows reading only. Locks apply to everyone, regardless of their role, until the lock is removed.', 'https://learn.microsoft.com/en-us/training/modules/describe-features-tools-azure-for-governance-compliance/'),
  ('aee0dbcb-300a-5a1b-b779-c200b2147946', 'Microsoft Purview is a family of data governance, risk and compliance solutions. It helps you discover, classify and manage data across your estate, including on-premises, multicloud and SaaS sources.', 'https://learn.microsoft.com/en-us/training/modules/describe-features-tools-azure-for-governance-compliance/'),
  ('50b1ad2e-b80f-5ce3-a69d-ff5124408d7d', 'Azure Policy evaluates resources against rules and reports compliance, and with effects such as deny it can prevent non-compliant resources from being created or changed. Policy is enforced at the Azure Resource Manager layer, so it applies whether you use the portal, command-line tools or templates.', 'https://learn.microsoft.com/en-us/training/modules/describe-features-tools-azure-for-governance-compliance/'),
  ('61b77e6d-ce06-5319-8f4e-a08d29f30620', 'Azure Cloud Shell is an authenticated, browser-accessible shell for managing Azure resources. You can choose Bash with Azure CLI or PowerShell, and nothing needs to be installed on your computer.', 'https://learn.microsoft.com/en-us/training/modules/describe-features-tools-manage-deploy-azure-resources/'),
  ('a72797cf-d6e7-51d9-9695-57642066d30a', 'Azure Arc extends Azure management and governance to resources running outside Azure, such as servers and Kubernetes clusters in on-premises datacentres or other clouds. They appear in Azure and can use tools such as Azure Policy and Azure Monitor.', 'https://learn.microsoft.com/en-us/training/modules/describe-features-tools-manage-deploy-azure-resources/'),
  ('ba1c7842-6dd2-587d-9f4e-0465e0f094c4', 'Infrastructure as code defines infrastructure in files that you can store in version control, review and redeploy. ARM templates describe the resources you want declaratively, so each deployment gives a consistent result.', 'https://learn.microsoft.com/en-us/training/modules/describe-features-tools-manage-deploy-azure-resources/'),
  ('ec660887-b5e7-579e-ba03-e8151a06c133', 'Azure Resource Manager is the deployment and management service for Azure. The portal, Azure CLI, PowerShell, SDKs and templates all send requests to the same Resource Manager API, which authenticates and authorises the request and applies policy and locks consistently.', 'https://learn.microsoft.com/en-us/training/modules/describe-features-tools-manage-deploy-azure-resources/'),
  ('b02a6a02-472a-50f6-ad65-8175084ce27e', 'Azure Service Health gives you a personalised view of the health of the Azure services and regions you use, including service issues, planned maintenance and health advisories, and can notify you through alerts.', 'https://learn.microsoft.com/en-us/training/modules/describe-monitoring-tools-azure/'),
  ('475ac71f-9407-566f-b6a3-06c02e81c74d', 'Azure Advisor analyses your deployed resources and usage and gives personalised recommendations in categories such as reliability, security, performance, cost and operational excellence.', 'https://learn.microsoft.com/en-us/training/modules/describe-monitoring-tools-azure/'),
  ('fea4d1fc-4971-54da-aa38-e980ece5672c', 'Azure Monitor collects metrics and logs from Azure resources. Log Analytics is the tool in the Azure portal for writing and running queries, using the Kusto Query Language, against the log data stored in a Log Analytics workspace.', 'https://learn.microsoft.com/en-us/training/modules/describe-monitoring-tools-azure/'),
  ('50a8be05-9e63-512e-bfdb-d47e6870e7ba', 'Application Insights is the application performance monitoring feature of Azure Monitor. It collects request rates, response times, failures and dependencies from a live app, and can detect anomalies and send alerts.', 'https://learn.microsoft.com/en-us/training/modules/describe-monitoring-tools-azure/')
) as v(question_id, explanation, reference_url)
on conflict (question_id) do update set explanation = excluded.explanation, reference_url = excluded.reference_url;

insert into public.option_solutions (option_id, is_correct, note)
select v.option_id::uuid, v.is_correct::boolean, v.note
from (values
  ('a255fdf2-7881-5732-84b3-db7bcee691ff', false, 'That is standalone computing. Cloud computing relies on network access to shared resources.'),
  ('075af511-dd83-59e1-be4b-43606910e783', false, 'That is traditional on-premises infrastructure, where you own and run the hardware.'),
  ('c93efd99-dbda-5321-a2f7-1891df53e5ae', true, null),
  ('d51ca0ba-f6de-5b47-9590-197c76e06b38', false, 'Cloud computing delivers digital computing services, not physical record storage.'),
  ('6535bed8-149e-5dac-9c41-766855b533fd', false, 'Microsoft maintains the physical hosts, but with infrastructure as a service the guest operating system belongs to the customer.'),
  ('1e075ab0-464b-559e-9396-ca7bafdca314', true, null),
  ('d8487be0-9722-5eb7-9021-0e872456ff44', false, 'Azure offers tools that can automate patching, but the customer still has to choose and configure them.'),
  ('f4d85a74-cc4b-5c9c-a076-14886ca091ff', false, 'Every operating system needs updates to fix security flaws and bugs.'),
  ('9882da3b-2d97-59e6-a52f-5991220dc16f', true, null),
  ('6af13d8a-cbf7-5d33-a4d4-cde56b7c7d29', false, 'Part of the workload stays on the hospital''s own servers, so it is not public cloud only.'),
  ('d762e9ae-aefa-58b9-9974-e2b0c337dde8', false, 'The website runs on Azure, a public cloud, so the setup is not private only.'),
  ('a0b9862d-246f-5b13-b2a5-11e08ec7721d', false, 'Serverless is a way of running code, not a cloud deployment model.'),
  ('efac24b4-cba1-5497-bc96-8f3d5aa76d2d', false, 'That is a flat fee. Consumption-based charges follow actual usage.'),
  ('fa8d290f-4221-5c75-b49e-69f8d48df214', false, 'Buying hardware is capital expenditure. The consumption model replaces it with usage-based spending.'),
  ('cdf8e986-b13b-5ba6-9103-68ebd0111e83', false, 'Consumption-based pricing removes the need to buy for peak demand in advance.'),
  ('3a2eb7ba-4f35-5148-b94d-ee5d6998c263', true, null),
  ('8c57b844-db75-5272-8561-e7f2c6725ff2', false, 'The provider is always responsible for the physical datacentre.'),
  ('04e35bba-08f5-5eb1-8c45-2dda3c823e05', true, null),
  ('63755ed2-7ea9-53fb-b31d-fd5c12ed024f', false, 'The provider always owns and operates the physical network.'),
  ('4d9461bb-c540-5186-8393-918f11998228', true, null),
  ('82c953f7-80a1-55b4-a2ee-a3b65608f61c', false, 'That describes IaaS, not serverless.'),
  ('97bd89f7-376d-5366-80fd-9eccf9bc2e05', false, 'That describes SaaS.'),
  ('ade86862-e0ca-53f0-a69d-afd3fe575793', false, 'Servers still exist. The platform manages them so you do not have to.'),
  ('e417dca8-783e-56bd-bc5f-ce66e5f2d59f', true, null),
  ('ae6d43cd-045e-5012-899b-e2ea473cae85', false, 'Vertical scaling makes one server bigger by adding CPU or memory. Here the number of servers grows.'),
  ('37bb28a4-796a-5199-93e4-7e778a19cbba', true, null),
  ('2e9ce360-2834-5762-a3ff-686462c3269c', false, 'Geo-replication copies data to another region for resilience. It does not add capacity for demand.'),
  ('fe309d02-e182-5da1-b66b-1baab6ea77f9', false, 'A hybrid connection links on-premises and cloud networks. It does not add capacity.'),
  ('c4579811-0b96-5802-a70a-8cfdbb120956', false, 'That is about steady response times, for example through autoscaling and load balancing, not about forecasting spend.'),
  ('b4452eb1-e0d3-5181-9323-7dca3f2efa94', false, 'Data sovereignty is about where data is stored and which laws apply to it.'),
  ('58259809-f71a-598b-b99a-2d0bf51f3d30', true, null),
  ('2e91b69a-7bd3-5af0-bc2a-e1d015e12d8e', false, 'Manual capacity planning is the traditional approach that the cloud reduces.'),
  ('847abf88-79f8-5796-8714-202f6f88178a', false, 'In the cloud the provider handles physical hardware.'),
  ('8e2a4d45-f627-5604-985f-fe9c860b0df6', true, null),
  ('4624e556-a9b1-5072-8676-9765047b512e', false, 'Cloud capacity can be added on demand without buying and racking hardware.'),
  ('d2bd2001-c20b-5b15-a28f-ded03d1c6c42', true, null),
  ('1735e2bf-9018-5628-a6c1-2a04e826e8f6', true, null),
  ('1450caf0-cc57-5c51-90a6-8647d5675237', false, 'A bigger machine is still a single point of failure.'),
  ('97905abc-b48d-5393-8beb-f72be087d59f', false, 'Backups help you recover, but they do not keep the app running during an outage.'),
  ('1c62268a-fcc1-5818-82c2-129aedbe2edc', false, 'Network speed does not help if the datacentre itself fails.'),
  ('cb618872-ae8d-5537-8d63-aa43e90f0ded', false, 'With SaaS you use a finished application and cannot control the operating system.'),
  ('20c94ec1-4c96-52a9-8397-260d4e57ca5b', false, 'With PaaS the provider manages the operating system and runtime for you.'),
  ('c65930de-0403-51bc-b16b-03c9cff19865', false, 'Serverless hides the servers, which is the opposite of controlling the operating system.'),
  ('1b32635f-ba09-5b66-b073-38c2eae7bd43', true, null),
  ('5ce5c6f8-424a-5e67-be4b-44e698a488bb', false, 'With IaaS the team would still patch and manage the operating system.'),
  ('74530f05-2c32-5702-a6cc-0a6f8e18f610', true, null),
  ('9ea893d2-d265-59e0-b1ba-017bd067aa01', false, 'With SaaS the team would use a ready-made application rather than deploy its own code.'),
  ('d3bd4464-de01-5ac7-83bd-71dcab20faa0', false, 'A private datacentre means managing everything yourself.'),
  ('67659141-1706-5d16-a4d0-89ff9fbf50fb', true, null),
  ('b6ba319f-1f81-5a09-849e-1b65a6283dfb', false, 'Virtual machines are IaaS.'),
  ('77257234-b0ed-55bd-8886-2bb9d1ceca85', false, 'App Service is PaaS.'),
  ('7dcbeaad-9e59-5102-b970-1e44e9460dce', false, 'A virtual network is an infrastructure building block.'),
  ('bad889d9-ab4d-5b24-bd9e-61da3b51f379', false, 'It is the other way around: the customer manages the most in IaaS.'),
  ('636f145f-81ba-58c0-9802-9c66a254d19c', false, 'The split changes with the service type.'),
  ('0d21898a-a426-5b0d-861e-f5d286619b37', true, null),
  ('fe1a07b2-cbd5-5eb7-84c0-40c290f58d72', false, 'Customers always manage at least their data and identities.'),
  ('046efad1-0996-5892-990d-497833c379c3', false, 'Subscriptions are billing and access boundaries, unrelated to physical locations.'),
  ('4893f789-9be3-5f41-a574-9b0fa1ba83fb', true, null),
  ('bdee0fc4-ebb7-562b-a8ac-7b9b86a16e01', false, 'That describes a region pair.'),
  ('d62bfddc-390c-5e89-b74b-0b8788a3f0db', false, 'A subnet is a logical range of IP addresses, not a physical location.'),
  ('1b1a994c-d81e-5251-9435-6b28fca70fb3', false, 'Many newer regions are not paired and rely on availability zones for redundancy.'),
  ('94f3520e-7be6-51ae-a1d1-d27dcbc7a749', false, 'A pair is two separate regions, usually in the same geography.'),
  ('18c1aaac-fd78-5ebb-8664-1e7c66c50d52', true, null),
  ('397906fb-a02d-56c5-8628-030842cc98e4', false, 'Azure does not fail your workloads over for you. Design and test your own disaster recovery.'),
  ('8c9952f6-2d71-59e8-9ef2-a3e91ecf91f4', true, null),
  ('217859b5-fb27-550f-a8b9-9fefbcdb6e52', false, 'A management group sits above subscriptions, and resources sit inside resource groups.'),
  ('0a30ab9e-d197-5736-9ec0-6b650b81f701', false, 'A resource group does not contain subscriptions.'),
  ('1a3f8256-2bb7-5fb9-a15c-c351a8353f4f', false, 'This lists narrowest to broadest, the reverse of what was asked.'),
  ('a39d6cda-4b41-5ac5-9ba2-8468dd4e3aa5', false, 'Resource groups cannot be nested. Use management groups and subscriptions for higher-level organisation.'),
  ('3b4b6dde-c072-5599-962c-8f54e6972835', false, 'Each resource belongs to exactly one resource group at a time, although it can be moved.'),
  ('6fdd6650-41af-5bb7-8e58-6880eb71eff3', false, 'Resources in one group can be in different regions.'),
  ('177f555a-66d3-534b-9eea-33f233ecf9ee', true, null),
  ('bb50a234-92dd-527d-89f2-d0f7dc7b40b3', false, 'Availability sets reduce the impact of hardware faults. They do not create a separate legal boundary.'),
  ('1ab1c755-0169-5360-a8fd-5193bb94ee4e', true, null),
  ('ad153f6a-15d2-5e8d-b59f-b1ea851308fe', false, 'Locks prevent accidental changes or deletion. They do not isolate a workload legally.'),
  ('108302bb-8f5c-5f35-8d98-71cec6ca2f98', false, 'Region pairs support resilience, not separate compliance boundaries.'),
  ('8c5886b9-a8b0-52cb-9eb3-d0b5fdf81235', false, 'You would manage the virtual machine and its operating system.'),
  ('a9fe2d74-7827-58f4-acf1-2a2f2c67b120', true, null),
  ('0bc56dc2-2066-5d69-bd70-b88e07ede2be', false, 'Scale sets manage groups of virtual machines, which you still configure and patch.'),
  ('0e8a779e-bfe7-5c94-9cc4-631384cffe30', false, 'Virtual Desktop delivers desktops and apps to users. It does not run event-driven code.'),
  ('a0f5c0df-f7aa-5577-bceb-10dd85d8e398', false, 'That describes a virtual machine. Containers share the host''s operating system kernel.'),
  ('0d9b446a-088b-59c9-93b3-019a7c3c2c34', false, 'Because containers share a kernel, virtual machines generally offer a stronger isolation boundary.'),
  ('2e713611-ee99-5d9f-8c4d-b08bc2ac9e79', false, 'Containers can run many kinds of apps, on several Azure services.'),
  ('c0db8b6a-9be1-5cc3-a1e4-23a224577c7a', true, null),
  ('47941adf-fc3a-5fbd-844b-c2cd74cfbc92', true, null),
  ('8e826812-f5ff-5245-a19b-ef6c16cc892b', false, 'Availability sets spread VMs across fault and update domains to limit hardware and maintenance impact. They do not scale automatically.'),
  ('0a11537a-16ac-5d60-b7b8-8ea8b3f3be26', false, 'Virtual Desktop delivers desktops and apps. It is not for scaling a web tier.'),
  ('7b446b29-ef5d-515d-bdad-c35ec0638b59', false, 'Policy enforces rules on resources. It does not add or remove instances.'),
  ('830c8518-2733-5fff-bbb2-828b351b8fed', false, 'VPN Gateway sends encrypted traffic over the public internet.'),
  ('569e7f99-fb47-5646-8c41-fb83fa4fbdd6', false, 'Azure DNS resolves names. It does not create a network connection.'),
  ('1fb34388-a983-5c0e-9ba2-2eb32959d43f', false, 'Peering connects Azure virtual networks to each other, not a datacentre to Azure.'),
  ('2de55604-b250-5398-a54c-c0926289e94c', true, null),
  ('c1809b03-b434-50bc-a6a0-66e110ba9aa3', false, 'That exposes the machines to the internet and does not give private access to the storage account.'),
  ('cd183eb4-3e5b-53f0-8996-1ec8fa9cebbf', false, 'VM size affects compute capacity, not network paths.'),
  ('df60adfa-9a9b-5b14-8f5a-55b6a926ae31', true, null),
  ('6235fb3a-7e0a-5962-8d4e-77f8423d90ff', false, 'DNS resolves names to addresses. It does not create a private network path.'),
  ('39505a19-90db-5718-ac7c-1310977577ae', true, null),
  ('847dea11-8627-5fe9-a87e-9299e8d1a9ac', false, 'Queue Storage holds messages that pass between application components.'),
  ('bf28ed9f-3316-541c-9a13-60690c6ca7f4', false, 'Table Storage keeps structured NoSQL data, not large files.'),
